func (m *DepthUpdate) AsksId() int {
	return 8
}

func (m *DepthUpdate) Asks() *DepthUpdateAsks {
	m._Asks.WrapForDecode(m.buffer, m.sbePositionPtr(), m.actingVersion, m.bufferLength)
	return &m._Asks
}

func (m *DepthUpdate) AsksCount(count uint16) *DepthUpdateAsks {
	m._Asks.WrapForEncode(m.buffer, count, m.sbePositionPtr(), m.actingVersion, m.bufferLength)
	return &m._Asks
}

func (m *DepthUpdate) AsksSinceVersion() uint64 {
	return 0
}

func (m *DepthUpdate) AsksInActingVersion() bool {
	return true
}

func (writer *DepthUpdate) String() string {
	var builder strings.Builder
	builder.WriteString("{\"Name\": \"DepthUpdate\", ")
	builder.WriteString(fmt.Sprintf("\"sbeTemplateId\": %d", writer.SbeTemplateId()))
	builder.WriteString(", ")

	builder.WriteString(`"symbolId": `)
	builder.WriteString(fmt.Sprintf(`"%v"`, writer.SymbolId()))

	builder.WriteString(", ")
	builder.WriteString(`"bookEpoch": `)
	builder.WriteString(fmt.Sprintf(`"%v"`, writer.BookEpoch()))

	builder.WriteString(", ")
	builder.WriteString(`"firstUpdateId": `)
	builder.WriteString(fmt.Sprintf(`"%v"`, writer.FirstUpdateId()))

	builder.WriteString(", ")
	builder.WriteString(`"lastUpdateId": `)
	builder.WriteString(fmt.Sprintf(`"%v"`, writer.LastUpdateId()))

	builder.WriteString(", ")
	builder.WriteString(`"transactTsNs": `)
	builder.WriteString(fmt.Sprintf(`"%v"`, writer.TransactTsNs()))

	builder.WriteString(", ")
	builder.WriteString(`"sendTsNs": `)
	builder.WriteString(fmt.Sprintf(`"%v"`, writer.SendTsNs()))

	builder.WriteString(", ")
	{
		atLeastOne := false
		builder.WriteString(`"bids": [`)
		writer.Bids().ForEach(
			func(value *DepthUpdateBids) {
				if atLeastOne {
					builder.WriteString(", ")
				}
				atLeastOne = true
				builder.WriteString(value.String())
			})
		builder.WriteString("]")
	}

	builder.WriteString(", ")
	{
		atLeastOne := false
		builder.WriteString(`"asks": [`)
		writer.Asks().ForEach(
			func(value *DepthUpdateAsks) {
				if atLeastOne {
					builder.WriteString(", ")
				}
				atLeastOne = true
				builder.WriteString(value.String())
			})
		builder.WriteString("]")
	}

	builder.WriteString("}")

	return builder.String()
}

func (m *DepthUpdate) Skip() {
	for BidsGroup := m.Bids(); BidsGroup.HasNext(); {
		BidsGroup.Next().Skip()
	}
	for AsksGroup := m.Asks(); AsksGroup.HasNext(); {
		AsksGroup.Next().Skip()
	}
}

func (m *DepthUpdate) IsConstLength() bool {
	return false
}

func (m *DepthUpdate) ComputeLength(
	BidsLength int,
	AsksLength int) (int, error) {
	length := uint64(m.SbeBlockLength())

	length += m.Bids().SbeHeaderSize()
	if BidsLength > 65534 {
		panic(fmt.Sprintf("BidsLength outside of allowed range [E110]"))
	}
	length += uint64(BidsLength) * m.Bids().SbeBlockLength()

	length += m.Asks().SbeHeaderSize()
	if AsksLength > 65534 {
		panic(fmt.Sprintf("AsksLength outside of allowed range [E110]"))
	}
	length += uint64(AsksLength) * m.Asks().SbeBlockLength()

	return int(length), nil
}
